  });
  it("prefers existing completed over legacy done on load", () => {
    const path = join(mkdtempSync(join(tmpdir(), "todo-")), "todos.json");
    writeFileSync(path, JSON.stringify([{ id: 1, title: "x", done: false, completed: true }]));
    expect(load(path)).toEqual([{ id: 1, title: "x", completed: true }]);
  });
});

